import sqlite3
DB_PATH = 'ticketing.db'

def revoke_box_office_staff_access(event_id: int, staff_id: int) -> dict:
    if event_id <= 0 or staff_id <= 0:
        return {'ok': False, 'error': 'invalid ids'}
    conn = sqlite3.connect(DB_PATH)
    try:
        cur = conn.execute('DELETE FROM event_staff WHERE event_id = ? AND staff_id = ?', (event_id, staff_id))
        if cur.rowcount == 0:
            return {'ok': False, 'error': 'staff assignment not found'}
        conn.execute('DELETE FROM staff_permissions WHERE event_id = ? AND staff_id = ?', (event_id, staff_id))
        conn.commit()
        # Look up how many staff remain assigned to the event
        row = conn.execute('SELECT COUNT(*) FROM event_staff WHERE event_id = ?', (event_id,)).fetchone()
        remaining_staff = row[0] if row else 0
    finally:
        conn.close()
    return {'ok': True, 'event_id': event_id, 'staff_id': staff_id, 'remaining_staff': remaining_staff}
